const items = $input.all();

return items.map(item => {
  const article = item.json;

  const cleanText = String(
    article.contentSnippet || article.content || ""
  )
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 1500);

  return {
    json: {
      title: article.title || "",
      source: "CBC Technology",
      url: article.link || "",
      published: article.isoDate || article.pubDate || "",
      description: cleanText
    }
  };
});

const results = $input.all();
const articles = $("Code in JavaScript").all();

const entries = results.map((item, i) => {
  const article = articles[i]?.json || {};
  const response = String(item.json.content || "");

  const relevance =
    response.match(/Relevance:\s*(High|Medium|Low)/i)?.[1] || "Low";

  const reason =
    response.match(/Reason:\s*([\s\S]*?)(?=\nSummary:|$)/i)?.[1]?.trim() || "";

  const summary =
    response.match(/Summary:\s*([\s\S]*)/i)?.[1]?.trim() || "";

  return {
    ...article,
    relevance,
    reason,
    summary
  };
});

const rank = { High: 0, Medium: 1, Low: 2 };

entries.sort((a, b) =>
  rank[a.relevance] - rank[b.relevance]
);

const lines = [
  "# Canada-Relevance AI News Digest",
  "",
  `Generated: ${new Date().toISOString()}`,
  "",
  `Articles analyzed: ${entries.length}`,
  ""
];

for (const entry of entries) {
  lines.push(
    `## ${entry.relevance} — ${entry.title}`,
    "",
    `**Source:** ${entry.source}`,
    "",
    `**Published:** ${entry.published}`,
    "",
    `**Summary:** ${entry.summary}`,
    "",
    `**Canadian relevance:** ${entry.reason}`,
    "",
    `**Original article:** ${entry.url}`,
    "",
    "---",
    ""
  );
}

return [{
  json: {
    markdown: lines.join("\n"),
    articles: entries
  }
}];
